const __pageData = JSON.parse('{"title":"Department of Justice","description":"","frontmatter":{"title":"Department of Justice","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["doj","law-enforcement","slush-fund","settlements","corruption"],"sources":["raw/america-for-sale-part-2.md","raw/badlands-brief-0a2.md","raw/badlands-brief-143.md","raw/badlands-brief-05f.md","raw/badlands-brief-144.md","raw/badlands-brief-1ce.md","raw/badlands-brief-1ae.md","raw/badlands-brief-1ef.md","raw/badlands-brief-2c0.md","raw/badlands-brief-2c5.md","raw/badlands-brief-323.md","raw/badlands-brief-40d.md","raw/badlands-brief-509.md","raw/badlands-brief-625.md","raw/badlands-brief-707.md","raw/badlands-brief-739.md","raw/badlands-brief-7bf.md","raw/badlands-brief-70c.md","raw/badlands-brief-774.md","raw/badlands-brief-8c2.md","raw/badlands-brief-a6b.md","raw/badlands-brief-b62.md","raw/badlands-brief-c91.md","raw/badlands-brief-b82.md","raw/badlands-brief-d3b.md","raw/badlands-brief-e15.md","raw/badlands-news-brief-08c.md","raw/badlands-news-brief-090.md","raw/badlands-news-brief-096.md","raw/badlands-news-brief-092.md","raw/badlands-news-brief-144.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-228.md","raw/badlands-news-brief-25f.md","raw/badlands-news-brief-3f0.md","raw/badlands-news-brief-3ae.md","raw/badlands-news-brief-42e.md","raw/badlands-news-brief-448.md","raw/badlands-news-brief-52f.md","raw/badlands-news-brief-541.md","raw/badlands-news-brief-582.md","raw/badlands-news-brief-6aa.md","raw/badlands-news-brief-6af.md","raw/badlands-news-brief-644.md","raw/badlands-news-brief-711.md","raw/badlands-news-brief-656.md","raw/badlands-news-brief-721.md","raw/badlands-news-brief-669.md","raw/badlands-news-brief-762.md","raw/badlands-news-brief-7bb.md","raw/badlands-news-brief-795.md","raw/badlands-news-brief-899.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/department-of-justice.md","filePath":"entities/department-of-justice.md","lastUpdated":null}');
